DW.analyse:
async function analyse(file,excerptSec){const id=file.name+'|'+file.size+'|'+(file.lastModified||0);const hit=await DB.get(id);if(hit)return Object.assign({cached:true},hit);
const ctx=new AC({sampleRate:44100});let buf;try{buf=await ctx.decodeAudioData(await file.arrayBuffer());}catch(e){ctx.close();throw new Error('decode: '+e.message);}
const sr=buf.sampleRate,dur=buf.duration;const want=Math.min(dur,excerptSec||120);const start=Math.max(0,Math.floor((dur-want)/2*sr));const n=Math.floor(want*sr);
const mono=new Float32Array(n),chs=buf.numberOfChannels;
for(let c=0;c<chs;c++){const d=buf.getChannelData(c);for(let i=0;i<n;i++)mono[i]+=d[start+i]/chs;}
let sum=0,zc=0;for(let i=1;i<n;i++){sum+=mono[i]*mono[i];if((mono[i]>=0)!==(mono[i-1]>=0))zc++;}
const E=await bootEssentia(),vec=E.arrayToVector(mono);
let bpm=0,conf=0,beats=[],key='?',scale='?',kstr=0;
try{const r=E.RhythmExtractor2013(vec,208,'multifeature',40);bpm=r.bpm;conf=r.confidence;beats=E.vectorToArray(r.ticks);['ticks','estimates','bpmIntervals'].forEach(k=>{if(r[k]&&r[k].delete)r[k].delete();});}catch(e){console.warn('rhythm',file.name,e);}
try{const k=E.KeyExtractor(vec,true,4096,4096,12,3500,60,25,.2,'bgate',sr,.0001,440,'cosine','hann');key=k.key;scale=k.scale;kstr=k.strength;}catch(e){console.warn('key',file.name,e);}
if(vec.delete)vec.delete();ctx.close();buf=null;
const rec={id,name:file.name.replace(/\.[^.]+$/,''),bpm:+bpm.toFixed(2),conf:+conf.toFixed(3),beats:beats.slice(0,900).map(x=>+x.toFixed(4)),key,scale,camelot:camelot(key,scale),kstr:+kstr.toFixed(3),rms:Math.sqrt(sum/n),zcr:zc/n,dur:+dur.toFixed(1),size:file.size};
await DB.put(rec);return rec;}

DW.sequence:
function sequence(corpus,opts){opts=opts||{};const maxStretch=opts.maxStretch!=null?opts.maxStretch:0.08;const minConf=opts.minConf!=null?opts.minConf:0.8;const pool=dedupe(corpus).filter(t=>t.bpm>60&&t.dur>75&&t.conf>minConf);if(!pool.length)return [];
const n=Math.min(opts.length||pool.length,pool.length);const w=Object.assign({key:.30,tempo:.30,energy:.40},opts.weights);
const used=new Set();let cur=pool.slice().sort((a,b)=>Math.abs(a.energy-arc(0,n))-Math.abs(b.energy-arc(0,n)))[0];
used.add(cur.id);const out=[cur];let tempo=cur.bpm;
for(let i=1;i<n;i++){const want=arc(i,n);let best=null,bs=-1;
for(const t of pool){if(used.has(t.id))continue;const stretch=Math.abs(tempo/t.bpm-1);if(stretch>maxStretch)continue;
const s=camScore(cur.camelot,t.camelot)*w.key+(1-stretch/maxStretch)*w.tempo+(1-Math.min(1,Math.abs(t.energy-want)/.30))*w.energy;
if(s>bs){bs=s;best=t;}}
if(!best)break;used.add(best.id);best._score=+bs.toFixed(3);best._stretch=+(tempo/best.bpm).toFixed(3);best._tempoAt=Math.round(tempo);out.push(best);tempo+=(best.bpm-tempo)*(opts.drift||0.35);cur=best;}
return out;}

DW.scan:
async scan(onProgress){if(!window.showDirectoryPicker)throw new Error('showDirectoryPicker unavailable (Chromium only)');await bootEssentia();const dir=await window.showDirectoryPicker({mode:'read'});const files=await walk(dir);corpus=[];let cached=0,failed=0;
for(let i=0;i<files.length;i++){if(onProgress)onProgress(i+1,files.length,files[i].name);try{const r=await analyse(files[i]);if(r.cached)cached++;corpus.push(r);}catch(e){failed++;console.warn(files[i].name,e.message);}}
normalise(corpus);LIB.dir=dir;LIB.files=new Map();for(const f of files)LIB.files.set(norm(f.name),f);
return{files:files.length,analysed:corpus.length,cached,failed};}

DWNAV.plan:
function plan(T,dest,corpus,opts){
  opts=opts||{};
  const maxHops=opts.maxHops||3, beam=opts.beam||12;
  if(reachable(T,dest))return{direct:true,hops:[],stretch:+(stretchFor(T,dest.bpm)*100).toFixed(1)};
  const seen=new Set([dest.name]);
  let frontier=[{T,path:[]}];
  for(let depth=1;depth<=maxHops;depth++){
   const next=[];
   for(const node of frontier){
    /* candidates playable from here, not already used */
    const cands=corpus.filter(t=>!seen.has(t.name)&&!node.path.find(p=>p.name===t.name)&&reachable(node.T,t));
    /* rank by how much closer they bring us to dest */
    const scored=cands.map(t=>{
      const T2=advance(node.T,t.bpm);
      const gap=stretchFor(T2,dest.bpm);
      const key=window.DW.camScore?window.DW.camScore(t.camelot,dest.camelot):0.5;
      return{t,T2,gap,key,score:gap-key*0.02};
    }).sort((a,b)=>a.score-b.score).slice(0,beam);
    for(const s of scored){
     if(stretchFor(s.T2,dest.bpm)<=GATE){
      return{direct:false,hops:node.path.concat([s.t]),
        finalStretch:+(stretchFor(s.T2,dest.bpm)*100).toFixed(1),
        endTempo:+s.T2.toFixed(1)};
     }
     next.push({T:s.T2,path:node.path.concat([s.t])});
    }
   }
   frontier=next.slice(0,beam*2);
   if(!frontier.length)break;
  }
  return{direct:false,hops:null,reason:'no route within '+maxHops+' hops at '+(GATE*100)+'% gate'};
 }

DWNAV.commit:
function(set,opts){
 opts=opts||{};
 const q=(this.queue||window.DWNAV.QUEUE);
 if(!q)return{ok:false,why:'nothing queued'};
 const st=window.DW.state, at=st.idx;
 const dest=set[q.idx];
 if(!dest)return{ok:false,why:'destination not in set'};

 const insert = q.mode==='route' ? q.hops.concat([dest]) : [dest];

 /* remove the destination from wherever it was, so it does not play twice.
    Only safe when it sits AFTER the current position. */
 const out=set.slice();
 if(q.idx>at) out.splice(q.idx,1);
 out.splice(at+1,0,...insert);

 /* the rolling target changes, so every _stretch after the splice is now
    wrong. Recompute the tail exactly as the sequencer would. */
 const DRIFT=this.DRIFT||0.35;
 let T=st.tempo||out[at].bpm;
 for(let i=at+1;i<out.length;i++){
  out[i]._stretch=T/out[i].bpm;
  T=T+(out[i].bpm-T)*DRIFT;
 }
 return{ok:true,set:out,inserted:insert.length,at:at+1,
  ladder:insert.map(t=>Math.round(t.bpm)),
  endTempo:+T.toFixed(1)};
}

DWNAV.resequenceTail:
function(set,fromIdx,startTempo){
 const DRIFT=this.DRIFT||0.35, GATE=this.GATE||0.08;
 const head=set.slice(0,fromIdx+1);
 let pool=set.slice(fromIdx+1);
 const out=[]; let T=startTempo; let dropped=0;
 const camScore=(a,b)=>window.DW.camScore?window.DW.camScore(a,b):0.5;
 let prev=set[fromIdx];
 while(pool.length){
  const ok=pool.filter(t=>Math.abs(T/t.bpm-1)<=GATE);
  if(!ok.length)break;                       /* gate exhausted — stop, do not degrade */
  /* same scoring shape as the sequencer: key, tempo proximity, energy step */
  let best=null,bs=-1;
  for(const t of ok){
   const s=camScore(prev.camelot,t.camelot)*0.30
         +(1-Math.abs(T/t.bpm-1)/GATE)*0.30
         +(1-Math.min(1,Math.abs((t.energy||.5)-(prev.energy||.5))*2))*0.40;
   if(s>bs){bs=s;best=t;}
  }
  best._stretch=T/best.bpm;
  out.push(best);
  pool=pool.filter(t=>t!==best);
  T=T+(best.bpm-T)*DRIFT;
  prev=best;
 }
 dropped=pool.length;
 return{set:head.concat(out),kept:out.length,dropped,endTempo:+T.toFixed(1)};
}

DWNAV.dwellFor:
function(mode,xfade){
 const x=xfade||16;
 if(mode==='fast')  return Math.max(N.DWELL.min, x*2+8);   /* in, 8s, out */
 if(mode==='brisk') return Math.max(x*2+40, N.DWELL.brisk);
 return N.DWELL.full;
}

DWNAV.planFast:
function(T,dest,corpus,opts){
 opts=opts||{};
 const xf=opts.xfade||16, dwell=N.dwellFor('fast',xf);
 const p=N.plan(T,dest,corpus,{maxHops:opts.maxHops||16,beam:opts.beam||24});
 if(p.direct)return Object.assign({},p,{seconds:0,mode:'direct'});
 if(!p.hops)return p;
 /* every intermediate is a stepping stone; the destination plays in full */
 const hops=p.hops.map(t=>Object.assign(Object.create(Object.getPrototypeOf(t)),t,{_dwell:dwell,_stepping:true}));
 const secs=hops.length*dwell;
 return Object.assign({},p,{hops,seconds:secs,minutes:+(secs/60).toFixed(1),
   dwellSec:dwell,mode:'fast',
   vsNormal:+((p.hops.length*N.DWELL.full)/60).toFixed(1)});
}

DWNAV.queueTime:
function(set){
 let s=0;
 Q.forEach(e=>{
  const hops=(e.hops||[]).length;
  const d=e.dwellSec||N.DWELL.full;
  s+=hops*d+N.DWELL.full;             /* stepping stones + the destination */
 });
 return{seconds:Math.round(s),minutes:+(s/60).toFixed(1),entries:Q.length};
}

spectrum.draw:
(c,w,h,T,D)=>{c.fillStyle=T.bg;c.fillRect(0,0,w,h);if(!D.freq)return;
 const n=Math.max(16,Math.floor(w/9)),bw=w/n;
 for(let i=0;i<n;i++){const lo=Math.floor(Math.pow(i/n,2.2)*D.freq.length);
  const hb=Math.max(lo+1,Math.floor(Math.pow((i+1)/n,2.2)*D.freq.length));
  let m=0;for(let j=lo;j<hb;j++)m=Math.max(m,D.freq[j]);const bh=(m/255)*(h-3);
  const gr=c.createLinearGradient(0,h,0,h-bh);gr.addColorStop(0,col(52)||T.ac2);gr.addColorStop(1,col(72)||T.ac);
  c.fillStyle=gr;T.g(c,col(52)||T.ac2,7);c.fillRect(i*bw+1,h-bh,bw-2,bh);}c.shadowBlur=0;}

chroma.draw:
(c,w,h,T,D)=>{c.fillStyle=T.bg;c.fillRect(0,0,w,h);if(!D.freq)return;
 const b=new Float32Array(12),N=D.freq.length*2;
 for(let i=1;i<D.freq.length;i++){const f=i*44100/N;if(f<55||f>5000)continue;
  b[((Math.round(69+12*Math.log2(f/440))%12)+12)%12]+=D.freq[i]/255;}
 let mx=0;for(const v of b)mx=Math.max(mx,v);
 const cx=w/2,cy=h/2,r=Math.min(w,h)/2-13;
 for(let i=0;i<12;i++){const a=(i/12)*Math.PI*2-Math.PI/2,v=mx?b[i]/mx:0;
  c.strokeStyle=T.line;c.lineWidth=1;c.beginPath();c.moveTo(cx,cy);c.lineTo(cx+Math.cos(a)*r,cy+Math.sin(a)*r);c.stroke();
  if(v>.12){const k=v>.6?(col(58)||T.ac2):(col(70)||T.ac);c.strokeStyle=k;c.lineWidth=3;T.g(c,k,10);
   c.beginPath();c.moveTo(cx,cy);c.lineTo(cx+Math.cos(a)*r*v,cy+Math.sin(a)*r*v);c.stroke();c.shadowBlur=0;}
  c.fillStyle=v>.5?(col(75)||T.ac):T.dim;c.font='9px '+T.fn;c.textAlign='center';c.textBaseline='middle';
  c.fillText(PITCH[i],cx+Math.cos(a)*(r+8),cy+Math.sin(a)*(r+8));}}

scope.draw:
(c,w,h,T,D)=>{c.fillStyle=T.bg;c.fillRect(0,0,w,h);if(!D.wave)return;
 const k=col(62)||T.ac;c.strokeStyle=k;c.lineWidth=1.5;T.g(c,k,9);c.beginPath();
 const s=D.wave.length/w;for(let x=0;x<w;x++){const v=(D.wave[Math.floor(x*s)]-128)/128;
  const y=h/2+v*(h/2-3);x?c.lineTo(x,y):c.moveTo(x,y);}c.stroke();c.shadowBlur=0;}

position.draw:
(c,w,h,T,D)=>{
 c.fillStyle=T.bg;c.fillRect(0,0,w,h);
 const t=D.set[D.state.idx];if(!t){c.fillStyle=T.dim;c.font='9px '+T.fn;c.textAlign='center';
  c.textBaseline='middle';c.fillText('no track playing',w/2,h/2);return;}
 const pad=10,bw=w-pad*2,y=h/2;
 const rate=t._stretch||1,entry=(t.beats&&t.beats[0])||0;
 const dur=(t.dur-entry)/rate;
 const el=window.__TRANS_LEFT!=null?Math.max(0,dur-16-window.__TRANS_LEFT):0;
 const frac=Math.max(0,Math.min(1,el/dur));
 c.strokeStyle=T.line;c.lineWidth=1;c.strokeRect(pad,y-11,bw,22);
 /* beat ticks across the whole track */
 if(t.beats&&t.beats.length){c.fillStyle=T.line;
  for(let i=0;i<t.beats.length;i+=16){const f=((t.beats[i]-entry)/rate)/dur;
   if(f<0||f>1)continue;c.fillRect(pad+f*bw,y-9,1,18);}}
 const k=col(60)||T.ac;c.fillStyle=k;T.g(c,k,8);c.fillRect(pad,y-10,frac*bw,20);c.shadowBlur=0;
 /* exit marker — where the blend begins */
 const ex=(dur-16)/dur;const k2=col(56)||T.ac2;
 c.fillStyle=k2;T.g(c,k2,10);c.fillRect(pad+ex*bw-1,y-14,2,28);c.shadowBlur=0;
 c.font='8px '+T.fn;c.textBaseline='middle';
 c.fillStyle=T.dim;c.textAlign='left';c.fillText(Math.floor(el/60)+':'+String(Math.floor(el%60)).padStart(2,'0'),pad,y-20);
 c.textAlign='right';c.fillText('blend at '+Math.floor((dur-16)/60)+':'+String(Math.floor((dur-16)%60)).padStart(2,'0'),w-pad,y-20);
 c.textAlign='center';c.fillStyle=k2;c.fillText(t.name.replace(/^[^-]+-\s*/,'').slice(0,40),w/2,y+22);
}

loudness.draw:
(c,w,h,T,D)=>{
 c.fillStyle=T.bg;c.fillRect(0,0,w,h);
 if(!D.freq){return;}
 /* crude K-weighting: de-emphasise below ~100Hz, emphasise 1-4kHz */
 let sum=0,wt=0;const N=D.freq.length*2;
 for(let i=1;i<D.freq.length;i++){const f=i*44100/N;
  let g2=1;if(f<100)g2=0.25;else if(f>1000&&f<4000)g2=1.4;else if(f>10000)g2=0.7;
  const m=D.freq[i]/255;sum+=m*m*g2;wt+=g2;}
 const rms=Math.sqrt(sum/(wt||1));
 const lufs=rms>0.0001?(20*Math.log10(rms)-10):-70;
 const L=window.__LOUD;L.hist[L.i]=lufs;L.i=(L.i+1)%L.hist.length;if(L.filled<L.hist.length)L.filled++;
 let mean=0;for(let i=0;i<L.filled;i++)mean+=L.hist[i];mean/=(L.filled||1);
 const pad=8,gy=h-26;
 /* history trace */
 c.strokeStyle=T.line;c.lineWidth=1;
 [-14,-23].forEach(tgt=>{const y=gy-((tgt+40)/40)*(gy-pad);
  c.setLineDash([3,3]);c.beginPath();c.moveTo(pad,y);c.lineTo(w-pad,y);c.stroke();c.setLineDash([]);
  c.fillStyle=T.dim;c.font='7px '+T.fn;c.textAlign='left';c.textBaseline='bottom';
  c.fillText(tgt+' LUFS',pad+2,y-1);});
 const k=col(66)||T.ac;c.strokeStyle=k;c.lineWidth=1.5;T.g(c,k,7);c.beginPath();
 for(let i=0;i<L.filled;i++){const idx=(L.i+i)%L.hist.length;
  const x=pad+(i/(L.filled-1||1))*(w-pad*2);
  const y=gy-((Math.max(-40,Math.min(0,L.hist[idx]))+40)/40)*(gy-pad);
  i?c.lineTo(x,y):c.moveTo(x,y);}c.stroke();c.shadowBlur=0;
 c.font='11px '+T.fn;c.textAlign='center';c.textBaseline='middle';
 const over=mean>-12;c.fillStyle=over?'#ffb02e':(col(74)||T.ac);
 c.fillText(mean.toFixed(1)+' LU  \u00b7 relative',w/2,h-12);
}

journey.draw:
(c,w,h,T,D)=>{
 c.fillStyle=T.bg;c.fillRect(0,0,w,h);
 const S=D.set;if(!S.length){c.fillStyle=T.dim;c.font='9px '+T.fn;c.textAlign='center';
  c.textBaseline='middle';c.fillText('no set built',w/2,h/2);return;}
 const cx=w/2,cy=h/2,R2=Math.min(w,h)/2-14;
 const pt=cd=>{if(!cd||cd==='?')return null;const n=+cd.slice(0,-1),L=cd.slice(-1);
  if(isNaN(n))return null;const a=((n-1)/12)*Math.PI*2-Math.PI/2,rr=L==='A'?R2*0.60:R2;
  return[cx+Math.cos(a)*rr,cy+Math.sin(a)*rr];};
 c.strokeStyle=T.line;c.lineWidth=1;
 c.beginPath();c.arc(cx,cy,R2,0,7);c.stroke();
 c.beginPath();c.arc(cx,cy,R2*0.60,0,7);c.stroke();
 const idx=D.state.idx;
 for(let i=1;i<S.length;i++){const a=pt(S[i-1].camelot),b=pt(S[i].camelot);if(!a||!b)continue;
  const done=i<=idx;
  c.strokeStyle=done?(col(60,.75)||T.ac2):(T.line);
  c.lineWidth=done?1.4:0.8;c.globalAlpha=done?0.85:0.35;
  c.beginPath();c.moveTo(a[0],a[1]);c.lineTo(b[0],b[1]);c.stroke();}
 c.globalAlpha=1;
 const cur=pt(S[idx]&&S[idx].camelot);
 if(cur){const k=col(70)||T.ac;c.fillStyle=k;T.g(c,k,12);
  c.beginPath();c.arc(cur[0],cur[1],5,0,7);c.fill();c.shadowBlur=0;}
 c.fillStyle=T.dim;c.font='8px '+T.fn;c.textAlign='center';c.textBaseline='bottom';
 c.fillText((idx+1)+' of '+S.length+' \u00b7 harmonic path',cx,h-4);
}

polygraph.draw:
(c,w,h,T,D)=>{
 const P=window.__POLY,NCH=P.ch.length;
 if(!P.buf)P.buf=Array.from({length:NCH},()=>new Float32Array(P.n));
 /* sample */
 if(D.freq){const bd=(a,b)=>{let s=0,n2=0;for(let i=a;i<b&&i<D.freq.length;i++){s+=D.freq[i];n2++;}return n2?s/n2/255:0;};
  P.buf[0][P.i]=bd(0,12);P.buf[1][P.i]=bd(12,90);P.buf[2][P.i]=bd(90,D.freq.length);
  P.buf[3][P.i]=Math.min(1,(window.__LASTFLUX||0)*14);
  P.buf[4][P.i]=D.stereo?Math.min(1,D.stereo.width*2.2):0;
  P.i=(P.i+1)%P.n;if(P.filled<P.n)P.filled++;}
 c.fillStyle=T.bg;c.fillRect(0,0,w,h);
 const padL=42,padR=6,padT=6,padB=6;
 const gw=w-padL-padR,gh=h-padT-padB,rowH=gh/NCH;
 /* ruled chart paper */
 c.strokeStyle=T.line;c.lineWidth=1;c.globalAlpha=.55;
 for(let i=0;i<=NCH;i++){const y=padT+i*rowH;c.beginPath();c.moveTo(padL,y);c.lineTo(w-padR,y);c.stroke();}
 c.globalAlpha=.25;
 for(let x=0;x<=10;x++){const xx=padL+(x/10)*gw;c.beginPath();c.moveTo(xx,padT);c.lineTo(xx,h-padB);c.stroke();}
 c.globalAlpha=1;
 const cols=[window.__col(56)||T.ac2,window.__col(66)||T.ac,window.__col(74)||'#3ee68a','#ffb02e',window.__col(70)||T.ac];
 P.ch.forEach((ch,ci)=>{
  const y0=padT+ci*rowH,mid=y0+rowH/2,amp=rowH*0.42;
  c.fillStyle=T.dim;c.font='7.5px '+T.fn;c.textAlign='right';c.textBaseline='middle';
  c.fillText(ch.k,padL-6,mid);
  const col=cols[ci%cols.length];
  c.strokeStyle=col;c.lineWidth=1.3;T.g(c,col,6);c.beginPath();
  for(let k=0;k<P.filled;k++){const idx=(P.i+k)%P.n;
   const x=padL+(k/(P.filled-1||1))*gw;
   const y=mid-(P.buf[ci][idx]-0.5)*amp*2;
   k?c.lineTo(x,y):c.moveTo(x,y);}
  c.stroke();c.shadowBlur=0;
  /* pen head */
  const last=P.buf[ci][(P.i-1+P.n)%P.n];
  const py=mid-(last-0.5)*amp*2;
  c.fillStyle=col;T.g(c,col,10);c.beginPath();c.arc(w-padR-1,py,2.2,0,7);c.fill();c.shadowBlur=0;});
}

wayposts.draw:
function(c,w,h,T,D){
 c.fillStyle=T.bg;c.fillRect(0,0,w,h);
 const corpus=(window.DW&&window.DW.corpus)||[];
 if(!corpus.length){c.fillStyle=T.dim;c.font='9px '+T.fn;c.textAlign='center';
  c.textBaseline='middle';c.fillText('scan a library first',w/2,h/2);return;}

 const cx=w/2, cy=h/2, R0=Math.min(w,h)/2-16;
 const bpms=corpus.map(t=>t.bpm).filter(Boolean);
 const lo=Math.min(...bpms), hi=Math.max(...bpms);
 const llo=Math.log2(lo*0.97), lhi=Math.log2(hi*1.03);
 const rad = bpm => R0*0.22 + ((Math.log2(bpm)-llo)/(lhi-llo))*(R0*0.78);
 const ang = cam => {const n=parseInt(cam)||1; return ((n-1)/12)*Math.PI*2 - Math.PI/2;};
 const pos = t => {const a=ang(t.camelot), r=rad(t.bpm);
   /* minor inside, major nudged out slightly so A/B don't overlap */
   const off=(String(t.camelot).slice(-1)==='B')?4:-4;
   return [cx+Math.cos(a)*(r+off), cy+Math.sin(a)*(r+off)];};

 const nav=window.DWNAV, st=window.DW.state, S=window.__SET||[];
 const Tnow=st.tempo||120;

