  if(!m)return null;
  const bpm=m.bpm*(rate||1),per=60/bpm;
  c.textAlign='left';c.fillStyle=DM;c.fillText(label,pad,y-rowH/2-7);
  c.textAlign='right';c.fillStyle=colr;
  c.fillText(bpm.toFixed(1)+' bpm \u00b7 '+m.camelot+' \u00b7 \u00d7'+(rate||1).toFixed(3),w-pad,y-rowH/2-7);
  c.strokeStyle=LN;c.lineWidth=1;c.strokeRect(pad,y-rowH/2,inner,rowH);
  /* deck gain as a fill behind the grid */
  if(gain!=null){c.fillStyle=colr;c.globalAlpha=.10;c.fillRect(pad,y-rowH/2,inner*gain,rowH);c.globalAlpha=1;}
  const phase=(t%per)/per,n=Math.ceil(span/per)+1;
  let barCount=0;
  for(let k=0;k<n;k++){const tt=(k*per)-(phase*per),fr=tt/span;
   if(fr<0||fr>1)continue;const x=pad+fr*inner,down=(k%4)===0;
