   c.fillRect(x-(down?2:0.75),y-rowH/2+2,down?4:1.5,rowH-4);c.shadowBlur=0;
   if(down){c.fillStyle=DM;c.font='7px '+fn;c.textAlign='center';
    c.fillText(String(barCount),x,y+rowH/2+6);c.font='8px '+fn;}}
  return per;};
 const rateA=cur._stretch||1,rateB=nxt?(nxt._stretch||1):1;
 const left=window.__TRANS_LEFT;
