 const perA=row(cur,rateA,y1,col(60)||AC2,'OUTGOING',blending?1-prog:1);
 const perB=nxt?row(nxt,rateB,y2,col(72)||AC,'INCOMING',blending?prog:0):null;
 const by=y2+rowH/2+18;
 if(nxt&&perA&&perB){
  const drift=Math.abs(perA-perB)/Math.max(perA,perB),locked=drift<0.005;
  c.textAlign='center';c.font='9px '+fn;
  c.fillStyle=locked?(col(74)||'#3ee68a'):'#ffb02e';g(c,c.fillStyle,locked?8:5);
  c.fillText(locked?'\u25c9 PHASE LOCKED \u00b7 periods match':'\u25b3 DRIFT '+(drift*100).toFixed(2)+'%',w/2,by);
