 const direct=Math.abs(T/t.bpm-1)*100;
 if(direct<=8)return;                       /* no route needed */
 const fast=DWNAV.planFast(T,t,DW.corpus,{maxHops:16,beam:24});
 if(!fast.hops||!fast.hops.length)return;
 const norm=(fast.hops.length*DWNAV.DWELL.full)/60;
 const el2=document.createElement('span');
 el2.className='opt good';
 el2.innerHTML='<b>\u26a1 blend fast \u00b7 '+fast.hops.length+' quick passes</b>'+
  '<i>Same route, but each stepping stone plays only '+fast.dwellSec+'s \u2014 long enough to blend in and out. '+
  '<b style="display:inline;color:#3ee68a">'+fast.minutes+' min</b> instead of '+norm.toFixed(0)+'.'+
  '<span class="route">'+fast.hops.map(h=>Math.round(h.bpm)).join(' \u2192 ')+' \u2192 <b>'+Math.round(t.bpm)+'</b></span></i>';
 el2.onclick=ev=>{ev.stopPropagation();
  DWNAV.enqueue({idx,mode:'route',hops:fast.hops,dwellSec:fast.dwellSec});
  window.__qRender();pop.classList.remove('on');
  sr.getElementById('logLine').textContent='queued fast \u00b7 '+fast.hops.length+' passes \u00b7 '+fast.minutes+' min';};
 const bar=pop.querySelector('.navbar');
 pop.insertBefore(el2,bar);
}

globals.__qRender:
function(){
 const Q=DWNAV.queueList(),S=window.__SET||[];
 if(!Q.length){box.classList.add('hidden');return;}
 box.classList.remove('hidden');
 const t=DWNAV.queueTime(S);
 box.innerHTML='<u><span>up next \u00b7 '+Q.length+' queued</span><b id="qClear">clear all</b></u>'+
  Q.map((e,i)=>{const d=S[e.idx]||{name:'?'};
   const hops=(e.hops||[]).length;
   const badge=e.mode==='route'?(e.dwellSec&&e.dwellSec<100?'\u26a1':'\u21dd'):(e.mode==='force'?'\u26a0':'\u25b8');
   const secs=hops*(e.dwellSec||210)+210;
   return '<div class="qrow"><i>'+badge+'</i>'+
    '<s>'+clean(d.name).slice(0,26)+'</s>'+
    '<em>'+Math.round(d.bpm||0)+' \u00b7 '+Math.round(secs/60)+'m</em>'+
    '<span><span class="mv" data-up="'+i+'">\u25b4</span> <span class="x" data-rm="'+i+'">\u2715</span></span>'+
    (hops?'<span class="lad">via '+(e.hops.map(h=>Math.round(h.bpm)).join(' \u2192 '))+'</span>':'')+
    '</div>';}).join('')+
  '<div class="qfoot"><span>total '+t.minutes+' min</span><span id="qGo" style="cursor:pointer;color:#3ee68a">commit next \u25b8</span></div>';
 box.querySelectorAll('[data-rm]').forEach(e=>e.onclick=ev=>{ev.stopPropagation();DWNAV.removeAt(+e.dataset.rm);window.__qRender();});
 box.querySelectorAll('[data-up]').forEach(e=>e.onclick=ev=>{ev.stopPropagation();const i=+e.dataset.up;DWNAV.moveQueue(i,i-1);window.__qRender();});
 sr.getElementById('qClear').onclick=ev=>{ev.stopPropagation();DWNAV.clearQueue();window.__qRender();$('logLine').textContent='queue cleared';};
 sr.getElementById('qGo').onclick=ev=>{ev.stopPropagation();
  const r=DWNAV.commitAndRepair(window.__SET);
  if(!r.ok){$('logLine').textContent=r.why;return;}
  window.__SET=r.set;window.__renderList&&window.__renderList();window.__bindRows&&window.__bindRows();
  DWNAV.dequeue();window.__qRender();
  $('logLine').textContent='committed \u00b7 '+r.inserted+' inserted \u00b7 tail kept '+r.tailKept+', dropped '+r.tailDropped;};
}

transport.innerOnclick:
async()=>{if(!window.__SET){$('logLine').textContent='build a set first';return;}
 const p=await payload();let h=await window.DWDIR.get();
 if(h&&!(await window.DWDIR.ready(h)))h=null;
 if(!h){dl(p.json,p.base+'.json','application/json');setTimeout(()=>dl(p.cue,p.base+'.cue','text/plain'),350);
  $('logLine').textContent='downloaded '+p.base+'.json + .cue \u00b7 '+p.sc.summary.tracks+' tracks';return;}
 try{await window.DWDIR.writeInto(h,p.base+'.json',p.json);await window.DWDIR.writeInto(h,p.base+'.cue',p.cue);
  $('logLine').textContent='saved to '+h.name+' \u00b7 '+p.base+' \u00b7 '+p.sc.summary.tracks+' tracks';}
 catch(e){$('logLine').textContent='save failed: '+e.message;}}

transport.onclick:
()=>{
 const inp=document.createElement('input');inp.type='file';inp.accept='.json,application/json';
 inp.onchange=async()=>{if(!inp.files[0])return;
  try{const r=DWSET.load(await inp.files[0].text());window.__SET=r.set;window.__renderList();
   $('logLine').textContent='loaded '+r.loaded+' tracks'+(r.missing.length?' \u00b7 '+r.missing.length+' missing from library':' \u00b7 complete');}
  catch(e){$('logLine').textContent='load failed: '+e.message;}};
 inp.click();
}

async()=>{
 if(window.DWLISTEN.active){window.DWLISTEN.stop();lb.textContent='\u25c9 listen to a tab';lb.className='';$('logLine').textContent='stopped listening';return;}
 try{$('logLine').textContent='pick a tab \u00b7 tick \u201cShare tab audio\u201d';
  const r=await window.DWLISTEN.tab();lb.textContent='\u25c9 listening';lb.className='hot';
  $('logLine').textContent='listening to '+r.source.slice(0,40)+' \u00b7 visuals only, no analysis';}
 catch(e){$('logLine').textContent=String(e.message||e);}}

shadowCSS:
:host{all:initial;--bg:var(--dw-color-bg,#04010f);--surf:var(--dw-color-surface,#0b0424);--line:var(--dw-color-line,#22125c);--txt:var(--dw-color-text,#e6ddff);--dim:var(--dw-color-dim,#7d6eb0);--ac:var(--dw-color-accent,#22e8ff);--ac2:var(--dw-color-accent-2,#ff2d95);--warn:var(--dw-color-warn,#ffb02e);--bad:var(--dw-color-bad,#ff5470);--good:var(--dw-color-good,#3ee68a);--fn:var(--dw-font-mono,ui-monospace,Menlo,monospace);--glow:var(--dw-glow,1);--scan:var(--dw-scanline-opacity,.26);--rad:var(--dw-border-radius,0px);display:block;height:100%;font-family:var(--fn);color:var(--txt)}
*{box-sizing:border-box;margin:0}
.app{display:grid;grid-template-columns:1fr minmax(230px,clamp(230px,22vw,340px));grid-template-rows:auto 1fr auto;height:100vh;background:var(--bg);gap:1px}
.app::before{content:'';position:fixed;inset:0;pointer-events:none;z-index:99;background:repeating-linear-gradient(180deg,transparent 0 2px,rgba(0,0,0,var(--scan)) 2px 3px)}
@media(max-width:720px){.app{grid-template-columns:1fr;grid-template-rows:auto auto 1fr auto}}
.bar{grid-column:1/-1;display:flex;align-items:center;gap:clamp(8px,2vw,22px);padding:8px 12px;background:var(--surf);border-bottom:1px solid var(--ac2);flex-wrap:wrap}
.bar h1{font-size:clamp(11px,1.4vw,15px);letter-spacing:.3em;color:var(--ac2);text-shadow:0 0 calc(10px*var(--glow)) var(--ac2);font-weight:700}
.kv{display:flex;flex-direction:column;line-height:1.15}
.kv u{text-decoration:none;font-size:7.5px;letter-spacing:.18em;text-transform:uppercase;color:var(--dim)}
.kv b{font-size:clamp(11px,1.3vw,15px);color:var(--ac);font-weight:500;text-shadow:0 0 calc(7px*var(--glow)) var(--ac)}
.kv b.p{color:var(--ac2);text-shadow:0 0 calc(7px*var(--glow)) var(--ac2)}
.kv b.w{color:var(--warn)}.kv b.g{color:var(--good)}
.main{display:grid;grid-template-rows:auto auto 1fr auto;gap:1px;min-height:0;overflow:hidden}
.strip{background:var(--surf);padding:6px 10px 8px;min-height:0}
.strip>u{display:block;text-decoration:none;font-size:7.5px;letter-spacing:.2em;text-transform:uppercase;color:var(--dim);margin-bottom:3px}
.tri{display:grid;grid-template-columns:2fr 1fr 1fr;gap:1px;min-height:0}
@media(max-width:900px){.tri{grid-template-columns:1fr 1fr}}
canvas{display:block;width:100%;height:100%;background:var(--bg)}
.cw{position:relative;min-height:0;height:100%}
.side{background:var(--surf);display:flex;flex-direction:column;min-height:0;border-left:1px solid var(--line)}
.side>u{display:block;text-decoration:none;font-size:7.5px;letter-spacing:.2em;text-transform:uppercase;color:var(--dim);padding:8px 10px 5px;border-bottom:1px solid var(--line)}
.list{flex:1;overflow-y:auto;min-height:0;scrollbar-width:thin;scrollbar-color:var(--line) transparent}
.tr{display:grid;grid-template-columns:26px 1fr auto;gap:6px;padding:4px 8px;font-size:10px;border-bottom:1px solid rgba(34,18,92,.5);align-items:center;cursor:pointer}
.tr:hover{background:rgba(34,232,255,.06)}
.tr i{color:var(--dim);font-style:normal;font-size:8.5px}
.tr s{text-decoration:none;color:var(--dim);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.tr em{font-style:normal;color:var(--dim);font-size:8.5px;white-space:nowrap}
.tr.now{background:rgba(255,45,149,.14);border-left:2px solid var(--ac2)}
.tr.now s{color:var(--ac2);text-shadow:0 0 calc(6px*var(--glow)) var(--ac2)}
.tr.now i,.tr.now em{color:var(--ac2)}
.tr.next{background:rgba(34,232,255,.08)}.tr.next s{color:var(--ac)}
.tr.done s,.tr.done i,.tr.done em{opacity:.4}
.tp{grid-column:1/-1;display:flex;gap:5px;padding:7px 10px;background:var(--surf);border-top:1px solid var(--line);flex-wrap:wrap;align-items:center}
button{background:none;border:1px solid var(--line);color:var(--dim);font:inherit;font-size:9px;letter-spacing:.14em;text-transform:uppercase;padding:6px 11px;cursor:pointer;border-radius:var(--rad)}
button:hover{border-color:var(--ac);color:var(--ac)}button.hot{border-color:var(--ac2);color:var(--ac2)}
.log{margin-left:auto;font-size:9px;color:var(--dim);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:44vw}

/* --- */
.app.mini{grid-template-columns:1fr!important;grid-template-rows:auto auto auto!important}
.app.mini .main>.strip:not(.keep){display:none}
.app.mini .tri{display:none}
.app.mini .side{display:none}
.app.mini .bar h1{font-size:11px}
.mini-host{position:fixed!important;inset:auto 12px 12px auto!important;width:min(380px,92vw)!important;height:auto!important;border:1px solid var(--dw-color-accent-2,#ff2d95);box-shadow:0 0 30px rgba(0,0,0,.6)}
.mini-host .app{height:auto!important}
.nowline{padding:6px 12px;font-size:10.5px;color:var(--txt);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;background:var(--surf);border-bottom:1px solid var(--line)}
.nowline b{color:var(--ac2)}

/* --- */
.split{display:inline-flex;position:relative}
.split button{border-radius:0}
.split .face{border-right:none;padding-right:9px}
.split .arrow{padding:6px 8px;border-left:1px solid var(--line)}
.split .menu{display:none;position:absolute;bottom:calc(100% + 4px);right:0;min-width:190px;background:var(--surf);border:1px solid var(--ac2);box-shadow:0 0 22px rgba(0,0,0,.7);z-index:50}
.split.open .menu{display:block}
.split .menu i{display:block;font-style:normal;padding:8px 11px;font-size:9.5px;letter-spacing:.12em;text-transform:uppercase;color:var(--dim);cursor:pointer;border-bottom:1px solid var(--line)}
.split .menu i:last-child{border-bottom:none}
.split .menu i:hover{background:rgba(34,232,255,.1);color:var(--ac)}
.split .menu u{display:block;text-decoration:none;padding:6px 11px;font-size:8px;letter-spacing:.14em;text-transform:uppercase;color:var(--dim);opacity:.7;border-bottom:1px solid var(--line)}

/* --- */

/* panels wrap into a grid instead of squeezing into one row */
.tri{display:grid;gap:1px;min-height:0;
  grid-template-columns:repeat(5,1fr);
  grid-auto-rows:1fr}

/* cinematic / very wide — keep all five across */
@media (min-aspect-ratio:2/1){.tri{grid-template-columns:repeat(5,1fr)}}

/* ordinary widescreen — three then two */
@media (max-aspect-ratio:2/1) and (min-aspect-ratio:7/5){.tri{grid-template-columns:repeat(3,1fr)}}

/* squarish — 2 x 3, panels become roughly square */
@media (max-aspect-ratio:7/5) and (min-aspect-ratio:3/4){.tri{grid-template-columns:repeat(2,1fr)}}

/* portrait / phone — single column, scrolls */
@media (max-aspect-ratio:3/4){.tri{grid-template-columns:1fr}}

/* narrow regardless of ratio */
@media (max-width:620px){.tri{grid-template-columns:1fr}}

/* when the panel row wraps it needs room and its own scroll */
.main{overflow:hidden}
.tri{overflow:auto;scrollbar-width:thin;scrollbar-color:var(--line) transparent}
.tri>.strip{min-height:clamp(120px,20vh,260px);display:flex;flex-direction:column}
.tri>.strip>.cw{flex:1;min-height:0}

/* --- */
.sel{position:relative;display:inline-flex}
.sel>button{min-width:118px;text-align:left}
.sel>button::after{content:'\25be';float:right;opacity:.7;margin-left:8px}
.sel .menu{display:none;position:absolute;bottom:calc(100% + 4px);left:0;min-width:180px;
  background:var(--surf);border:1px solid var(--ac2);box-shadow:0 0 22px rgba(0,0,0,.75);z-index:60;max-height:52vh;overflow:auto}
.sel.open .menu{display:block}
.sel .menu u{display:block;text-decoration:none;padding:6px 11px;font-size:8px;letter-spacing:.16em;
  text-transform:uppercase;color:var(--dim);opacity:.65;border-bottom:1px solid var(--line)}
.sel .menu i{display:flex;justify-content:space-between;align-items:center;font-style:normal;
  padding:8px 11px;font-size:9.5px;letter-spacing:.12em;text-transform:uppercase;color:var(--dim);
  cursor:pointer;border-bottom:1px solid var(--line)}
.sel .menu i:last-child{border-bottom:none}
.sel .menu i:hover{background:rgba(127,127,127,.14);color:var(--ac)}
.sel .menu i.on{color:var(--ac2);border-left:2px solid var(--ac2)}
.sel .menu i b{font-weight:400;font-size:8px;opacity:.6}
.sw{display:inline-flex;gap:2px;margin-left:8px}
.sw s{width:9px;height:9px;text-decoration:none;border:1px solid rgba(255,255,255,.25)}
/* --- */
.app[data-cols="1"] .tri{grid-template-columns:1fr!important}
.app[data-cols="2"] .tri{grid-template-columns:repeat(2,1fr)!important}
.app[data-cols="3"] .tri{grid-template-columns:repeat(3,1fr)!important}
.app[data-cols="5"] .tri{grid-template-columns:repeat(5,1fr)!important}
.app[data-side="hide"] .side{display:none}
.app[data-side="hide"]{grid-template-columns:1fr!important}
.app[data-side="wide"]{grid-template-columns:1fr minmax(360px,30vw)!important}
.app[data-dense="1"] .tri>.strip{min-height:90px}
.app[data-dense="1"] .strip{padding:3px 6px 4px}
.app[data-dense="1"] .tr{padding:2px 8px;font-size:9px}
/* --- */
.strip{position:relative}
.strip>u{display:flex;justify-content:space-between;align-items:center;gap:6px}
.swap{font-size:8px;letter-spacing:.1em;color:var(--dim);cursor:pointer;
  border:1px solid var(--line);padding:1px 5px;opacity:0;transition:opacity .15s;white-space:nowrap}
.strip:hover .swap{opacity:1}
.swap:hover{color:var(--ac);border-color:var(--ac)}
.pmenu{display:none;position:absolute;top:20px;right:6px;min-width:190px;z-index:70;
  background:var(--surf);border:1px solid var(--ac2);box-shadow:0 0 24px rgba(0,0,0,.8);max-height:60vh;overflow:auto}
.pmenu.open{display:block}
.pmenu i{display:flex;justify-content:space-between;align-items:center;font-style:normal;
  padding:7px 10px;font-size:9px;letter-spacing:.1em;text-transform:uppercase;color:var(--dim);
  cursor:pointer;border-bottom:1px solid var(--line)}
.pmenu i:last-child{border-bottom:none}
.pmenu i:hover{background:rgba(127,127,127,.14);color:var(--ac)}
.pmenu i.on{color:var(--ac2);border-left:2px solid var(--ac2)}
.pmenu i b{font-weight:400;font-size:7.5px;opacity:.55;margin-left:8px}
/* --- */
.hbtn{font-size:9px;width:14px;height:14px;line-height:12px;text-align:center;border:1px solid var(--line);
  color:var(--dim);cursor:help;border-radius:50%;opacity:0;transition:opacity .15s;flex:none}
.strip:hover .hbtn{opacity:1}
.hbtn:hover{color:var(--ac);border-color:var(--ac)}
.hcard{display:none;position:absolute;top:20px;left:6px;right:6px;z-index:80;padding:10px 12px;
  background:var(--surf);border:1px solid var(--ac);box-shadow:0 0 26px rgba(0,0,0,.85)}
.hcard.open{display:block}
.hcard h4{font-size:10px;letter-spacing:.14em;text-transform:uppercase;color:var(--ac);margin:0 0 6px;font-weight:500}
.hcard p{font-size:10px;line-height:1.55;color:var(--txt);margin:0 0 8px}
.hcard a{font-size:9px;color:var(--ac2);text-decoration:none;letter-spacing:.08em}
.hcard a:hover{text-decoration:underline}
.hcard em{font-style:normal;font-size:8px;color:var(--dim);display:block;margin-top:4px}
.strip>u{gap:5px}
/* --- */
.kv{position:relative;cursor:help}
.kv u{border-bottom:1px dotted transparent;transition:border-color .15s}
.kv:hover u{border-bottom-color:var(--dim)}
.tip{display:none;position:absolute;top:calc(100% + 8px);left:-6px;width:290px;z-index:200;
  padding:10px 12px;background:var(--surf);border:1px solid var(--ac);
  box-shadow:0 0 26px rgba(0,0,0,.85);cursor:default;text-align:left}
.kv:hover .tip,.tip:hover{display:block}
.tip::before{content:'';position:absolute;top:-8px;left:0;right:0;height:8px}
.tip h5{margin:0 0 5px;font-size:9.5px;letter-spacing:.14em;text-transform:uppercase;
  color:var(--ac);font-weight:500}
.tip p{margin:0 0 7px;font-size:10px;line-height:1.55;color:var(--txt);letter-spacing:0;text-transform:none}
.tip a{font-size:8.5px;color:var(--ac2);text-decoration:none;letter-spacing:.06em}
.tip a:hover{text-decoration:underline}
.tip em{font-style:normal;display:block;margin-top:4px;font-size:7.5px;color:var(--dim)}
@media(max-width:720px){.tip{width:240px;left:auto;right:-6px}}
/* --- */
.app[data-cols="6"] .tri{grid-template-columns:repeat(6,1fr)!important}
.app[data-cols="mega"] .tri{grid-template-columns:repeat(6,1fr)!important;grid-auto-rows:1fr!important;overflow:hidden}
.app[data-cols="mega"] .tri>.strip{min-height:0!important}
.app[data-cols="mega"] .main{grid-template-rows:auto 1fr auto!important}
.app[data-cols="mega"] .main>.strip.keep{height:clamp(46px,6vh,80px)!important}
.app[data-cols="mega"] .main>.strip:not(.keep):not(.tri){display:none}
.app[data-cols="mega"] .strip{padding:2px 5px 3px}
.app[data-cols="mega"] .strip>u{font-size:6.5px;margin-bottom:1px}
/* --- */
.lbl{cursor:help;position:relative;border-bottom:1px dotted transparent;transition:border-color .15s}
.strip:hover .lbl{border-bottom-color:var(--dim)}
.hcard{display:none}
.strip .lbl:hover ~ .hcard,.hcard:hover{display:block}
.hcard{top:18px}
/* collapsible panels */
.strip.collapsed .cw{display:none}
.strip.collapsed{min-height:0!important;height:auto!important}
.fold{font-size:9px;color:var(--dim);cursor:pointer;border:1px solid var(--line);padding:0 5px;
  opacity:0;transition:opacity .15s;flex:none;line-height:13px}
.strip:hover .fold{opacity:1}
.fold:hover{color:var(--ac);border-color:var(--ac)}
/* now playing, bottom right */
.np{position:fixed;right:12px;bottom:52px;z-index:150;width:min(320px,42vw);
  background:var(--surf);border:1px solid var(--ac2);box-shadow:0 0 26px rgba(0,0,0,.7);
  padding:9px 11px;font-size:10px;line-height:1.5;pointer-events:auto}
.np.hidden{display:none}
.np u{display:flex;justify-content:space-between;text-decoration:none;font-size:7.5px;letter-spacing:.2em;
  text-transform:uppercase;color:var(--dim);margin-bottom:5px}
.np u b{cursor:pointer;color:var(--dim)}
.np u b:hover{color:var(--ac)}
.np .t{color:var(--ac2);font-size:11.5px;word-break:break-word;margin-bottom:3px}
.np .m{color:var(--dim);font-size:9px;letter-spacing:.08em}
.np .nx{color:var(--dim);font-size:9px;margin-top:6px;padding-top:6px;border-top:1px solid var(--line);
  white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.np .nx s{text-decoration:none;color:var(--ac)}
.np .bar{height:3px;background:var(--line);margin-top:7px}
.np .bar i{display:block;height:100%;width:0;background:var(--ac2);transition:width .3s}
/* --- */
.app[data-cols="6"] .tri{grid-template-columns:repeat(6,1fr)!important}
.app[data-cols="4"] .tri{grid-template-columns:repeat(4,1fr)!important}
/* MEGA — every panel at once, other strips hidden, tight chrome */
.app[data-cols="mega"] .tri{grid-template-columns:repeat(6,1fr)!important;grid-auto-rows:1fr!important;overflow:hidden}
.app[data-cols="mega"] .tri>.strip{min-height:0!important}
.app[data-cols="mega"] .main{grid-template-rows:auto 1fr!important}
.app[data-cols="mega"] .main>.strip.keep{height:clamp(40px,5vh,70px)!important}
.app[data-cols="mega"] .main>.strip:not(.keep):not(.tri){display:none}
.app[data-cols="mega"] .strip{padding:2px 5px 3px}
.app[data-cols="mega"] .strip>u{font-size:6.5px;margin-bottom:1px}
@media(max-width:1400px){.app[data-cols="mega"] .tri{grid-template-columns:repeat(4,1fr)!important}}
@media(max-width:900px){.app[data-cols="mega"] .tri{grid-template-columns:repeat(3,1fr)!important}}
/* --- */
.np{width:min(360px,46vw);padding:10px 12px}
.np .grid{display:grid;grid-template-columns:repeat(4,1fr);gap:5px;margin-top:8px}
.np .grid div{border:1px solid var(--line);padding:4px 5px;text-align:center}
.np .grid u{display:block;text-decoration:none;font-size:6.5px;letter-spacing:.14em;text-transform:uppercase;color:var(--dim)}
.np .grid b{display:block;font-size:11px;color:var(--ac);margin-top:1px;font-weight:500}
.np .grid b.w{color:var(--warn)}.np .grid b.p{color:var(--ac2)}
.np .times{display:flex;justify-content:space-between;font-size:8.5px;color:var(--dim);margin-top:4px}
.np .blend{margin-top:7px;padding-top:6px;border-top:1px solid var(--line);font-size:9px;color:var(--dim)}
.np .blend b{color:var(--ac2)}
.np .blend.soon b{color:var(--warn)}
.np .art{display:flex;gap:8px;align-items:flex-start}
.np .bars{display:flex;gap:2px;align-items:flex-end;height:22px;margin-top:6px}
.np .bars i{flex:1;background:var(--line);transition:height .1s}

/* --- */
.np .art{color:var(--dim);font-size:9px;margin-top:2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.np .art b{color:var(--txt);font-weight:400}
.np .alb{color:var(--dim);font-size:8.5px;margin-top:1px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.np .src{color:var(--dim);font-size:7.5px;margin-top:3px;opacity:.7}
/* --- */
.gl{border-bottom:1px dotted currentColor;cursor:help;position:relative;opacity:.95}
.glpop{display:none;position:fixed;z-index:9999;width:min(300px,80vw);padding:10px 12px;
 background:var(--surf);border:1px solid var(--ac);box-shadow:0 0 28px rgba(0,0,0,.9);
 font-size:10px;line-height:1.55;letter-spacing:0;text-transform:none;text-align:left;color:var(--txt)}
.glpop.on{display:block}
.glpop h5{margin:0 0 5px;font-size:9.5px;letter-spacing:.14em;text-transform:uppercase;color:var(--ac);font-weight:500}
.glpop a{display:block;margin-top:7px;font-size:8.5px;color:var(--ac2);text-decoration:none}
.glpop a:hover{text-decoration:underline}
.glpop em{font-style:normal;display:block;margin-top:3px;font-size:7.5px;color:var(--dim)}
/* --- */
.navpop{position:fixed;z-index:9998;width:min(340px,86vw);background:var(--surf);
 border:1px solid var(--ac2);box-shadow:0 0 34px rgba(0,0,0,.9);font-size:10px;display:none}
.navpop.on{display:block}
.navpop h5{margin:0;padding:9px 12px;font-size:9.5px;letter-spacing:.14em;text-transform:uppercase;
 color:var(--ac2);border-bottom:1px solid var(--line);font-weight:500}
.navpop .tgt{padding:8px 12px;color:var(--txt);font-size:11px;border-bottom:1px solid var(--line)}
.navpop .tgt em{font-style:normal;display:block;color:var(--dim);font-size:9px;margin-top:2px}
.navpop .opt{display:block;padding:9px 12px;border-bottom:1px solid var(--line);cursor:pointer;color:var(--dim)}
.navpop .opt:last-child{border-bottom:none}
.navpop .opt:hover{background:rgba(127,127,127,.12)}
.navpop .opt b{display:block;color:var(--ac);font-weight:500;font-size:10px;letter-spacing:.08em;text-transform:uppercase}
.navpop .opt i{font-style:normal;display:block;color:var(--dim);font-size:9px;margin-top:2px;line-height:1.45}
.navpop .opt.warn b{color:var(--warn)} .navpop .opt.bad b{color:var(--bad)}
.navpop .opt.good b{color:#3ee68a}
.navpop .route{font-family:var(--fn);color:var(--ac2);font-size:9px;margin-top:3px;word-break:break-all}
.queued{background:rgba(62,230,138,.10)!important;border-left:2px solid #3ee68a!important}
.queued s{color:#3ee68a!important}
.navbar{padding:5px 12px;font-size:9px;color:var(--dim);border-top:1px solid var(--line);
 display:flex;justify-content:space-between;background:var(--bg)}
.navbar u{text-decoration:none;cursor:pointer;color:var(--ac)}
.navbar u:hover{text-decoration:underline}
/* --- */
.qbox{position:fixed;left:12px;bottom:52px;z-index:150;width:min(300px,40vw);
 background:var(--surf);border:1px solid #3ee68a;box-shadow:0 0 26px rgba(0,0,0,.75);font-size:10px}
.qbox.hidden{display:none}
.qbox u{display:flex;justify-content:space-between;text-decoration:none;padding:7px 10px;font-size:7.5px;
 letter-spacing:.2em;text-transform:uppercase;color:var(--dim);border-bottom:1px solid var(--line)}
.qbox u b{cursor:pointer;color:var(--dim)}.qbox u b:hover{color:var(--ac)}
.qrow{display:grid;grid-template-columns:16px 1fr auto auto;gap:6px;align-items:center;
 padding:6px 10px;border-bottom:1px solid var(--line)}
.qrow:last-child{border-bottom:none}
.qrow i{font-style:normal;color:#3ee68a;font-size:9px}
.qrow s{text-decoration:none;color:var(--txt);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.qrow em{font-style:normal;color:var(--dim);font-size:8.5px;white-space:nowrap}
.qrow .x{cursor:pointer;color:var(--dim);font-size:11px;line-height:1}
.qrow .x:hover{color:var(--bad)}
.qrow .mv{cursor:pointer;color:var(--dim);font-size:9px}
.qrow .mv:hover{color:var(--ac)}
.qfoot{padding:6px 10px;font-size:8.5px;color:var(--dim);border-top:1px solid var(--line);
 display:flex;justify-content:space-between;background:var(--bg)}
.qrow .lad{grid-column:2/-1;color:var(--ac2);font-size:8px;margin-top:1px}
